import PDFDocument from 'pdfkit';

/**
 * Generate a comprehensive PDF report for selling the scooter or personal records
 */
export async function generatePdfReport({ vehicle, fuelEntries, serviceEntries, dateRange }) {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({ margin: 40, size: 'A4' });
      const buffers = [];

      doc.on('data', (chunk) => buffers.push(chunk));
      doc.on('end', () => resolve(Buffer.concat(buffers)));

      // Title & Header (Instrument cluster theme)
      doc.fillColor('#09090b').fontSize(22).font('Helvetica-Bold').text('PITSTOP', 40, 40);
      doc.fontSize(10).font('Helvetica').fillColor('#71717a').text('VEHICLE HEALTH, MILEAGE & SERVICE AUDIT REPORT', 40, 68);

      doc.moveTo(40, 85).lineTo(555, 85).strokeColor('#e4e4e7').stroke();

      // Vehicle Overview Card
      let y = 100;
      doc.fontSize(12).font('Helvetica-Bold').fillColor('#09090b').text('Vehicle Specification', 40, y);
      y += 18;
      doc.fontSize(9).font('Helvetica').fillColor('#27272a');
      doc.text(`Model: ${vehicle.model} (${vehicle.year})`, 40, y);
      doc.text(`Registration: ${vehicle.registrationNumber}`, 200, y);
      doc.text(`Current Odometer: ${vehicle.currentOdometer.toLocaleString()} km`, 380, y);
      y += 14;
      doc.text(`Fuel Tank: ${vehicle.tankCapacity} L (Reserve: ${vehicle.reserveLevel} L)`, 40, y);
      doc.text(`Report Period: ${dateRange?.from || 'All time'} to ${dateRange?.to || 'Present'}`, 200, y);
      doc.text(`Generated: ${new Date().toLocaleDateString()}`, 380, y);

      y += 25;
      doc.moveTo(40, y).lineTo(555, y).strokeColor('#e4e4e7').stroke();
      y += 15;

      // Summary Statistics
      const totalFuelSpent = fuelEntries.reduce((sum, f) => sum + (f.totalCost || 0), 0);
      const totalFuelLitres = fuelEntries.reduce((sum, f) => sum + (f.litres || 0), 0);
      const totalServiceSpent = serviceEntries.reduce((sum, s) => sum + (s.cost || 0), 0);

      doc.fontSize(12).font('Helvetica-Bold').fillColor('#09090b').text('Cost & Mileage Summary', 40, y);
      y += 18;
      doc.fontSize(9).font('Helvetica').fillColor('#27272a');
      doc.text(`Total Fuel Spend: ₹${totalFuelSpent.toLocaleString()}`, 40, y);
      doc.text(`Total Fuel Filled: ${totalFuelLitres.toFixed(1)} L`, 200, y);
      doc.text(`Total Service Spend: ₹${totalServiceSpent.toLocaleString()}`, 380, y);
      y += 14;
      doc.text(`Total Scooter Expense: ₹${(totalFuelSpent + totalServiceSpent).toLocaleString()}`, 40, y);
      doc.text(`Total Service Records: ${serviceEntries.length}`, 200, y);
      doc.text(`Total Fuel Fills: ${fuelEntries.length}`, 380, y);

      y += 25;
      doc.moveTo(40, y).lineTo(555, y).strokeColor('#e4e4e7').stroke();
      y += 15;

      // Service History Table
      doc.fontSize(12).font('Helvetica-Bold').fillColor('#09090b').text('Service History', 40, y);
      y += 18;
      doc.fontSize(8).font('Helvetica-Bold').fillColor('#71717a');
      doc.text('Date', 40, y);
      doc.text('Odometer', 110, y);
      doc.text('Service Type', 180, y);
      doc.text('Workshop', 300, y);
      doc.text('Cost (₹)', 440, y);
      doc.text('Next Due', 500, y);
      y += 12;

      doc.font('Helvetica').fillColor('#27272a');
      serviceEntries.slice(0, 10).forEach((item) => {
        const itemDate = new Date(item.date).toLocaleDateString();
        doc.text(itemDate, 40, y);
        doc.text(`${item.odometer} km`, 110, y);
        doc.text(item.serviceType, 180, y);
        doc.text(item.workshop || '-', 300, y);
        doc.text(`₹${item.cost}`, 440, y);
        doc.text(item.nextDueKm ? `${item.nextDueKm} km` : '-', 500, y);
        y += 14;
        if (y > 750) {
          doc.addPage();
          y = 40;
        }
      });

      y += 15;
      if (y > 680) {
        doc.addPage();
        y = 40;
      }

      // Recent Fuel Logs
      doc.fontSize(12).font('Helvetica-Bold').fillColor('#09090b').text('Recent Fuel Logs', 40, y);
      y += 18;
      doc.fontSize(8).font('Helvetica-Bold').fillColor('#71717a');
      doc.text('Date', 40, y);
      doc.text('Odometer', 110, y);
      doc.text('Litres', 180, y);
      doc.text('Rate/L', 240, y);
      doc.text('Total (₹)', 300, y);
      doc.text('Full Tank', 380, y);
      doc.text('Station', 450, y);
      y += 12;

      doc.font('Helvetica').fillColor('#27272a');
      fuelEntries.slice(0, 10).forEach((item) => {
        doc.text(new Date(item.date).toLocaleDateString(), 40, y);
        doc.text(`${item.odometer} km`, 110, y);
        doc.text(`${item.litres} L`, 180, y);
        doc.text(`₹${item.pricePerLitre}`, 240, y);
        doc.text(`₹${item.totalCost}`, 300, y);
        doc.text(item.isFullTank ? 'Yes' : 'No', 380, y);
        doc.text(item.station || '-', 450, y);
        y += 14;
        if (y > 750) {
          doc.addPage();
          y = 40;
        }
      });

      // Footer
      doc.fontSize(8).fillColor('#a1a1aa').text('Generated by PitStop — Personal Scooter Dashboard', 40, 790, { align: 'center' });

      doc.end();
    } catch (err) {
      reject(err);
    }
  });
}

/**
 * Generate CSV data for export
 */
export function generateCsvReport({ _vehicle, fuelEntries, serviceEntries, odometerReadings }) {
  let csv = 'SECTION,DATE,ODOMETER,DETAIL_1,DETAIL_2,COST,NOTES\n';

  fuelEntries.forEach((f) => {
    csv += `Fuel,${new Date(f.date).toISOString().slice(0, 10)},${f.odometer},${f.litres} L,₹${f.pricePerLitre}/L,${f.totalCost},"${(f.station || '').replace(/"/g, '""')}"\n`;
  });

  serviceEntries.forEach((s) => {
    csv += `Service,${new Date(s.date).toISOString().slice(0, 10)},${s.odometer},"${s.serviceType}","${(s.workshop || '').replace(/"/g, '""')}",${s.cost},"${(s.notes || '').replace(/"/g, '""')}"\n`;
  });

  odometerReadings.forEach((o) => {
    csv += `Odometer,${new Date(o.date).toISOString().slice(0, 10)},${o.reading},"${o.source}",,,"${(o.note || '').replace(/"/g, '""')}"\n`;
  });

  return csv;
}
